// GroupStatusVectorsTests.swift
//
// The shared vectors (LXMF-rust tests/group_status_vectors.json, generated by the web's
// tools/group_status_vectors.mjs; the copy this runs on is rust/retichat-ffi/tests/data/, which a
// cargo test holds to LXMF-rust's own) run through the Swift layer: GroupStatusEngine with the
// group rule (DeliveryPolicy) in front of it, the native layer behind FakeGroupNative (real
// Ed25519 over the vectors' real packed messages: tests/GroupStatusFixtures.swift), and the store in
// memory. The glue crate runs the same file against the real library (cargo test), and
// tests/DistroChannelsFFITests.swift unpacks one of its messages through the real library.
// Retichat-android's GroupStatusVectorsTest.
//
// Run from the workspace root with:
//
//   swiftc -parse-as-library -o /private/tmp/claude-501/group-status-vectors \
//     Retichat-ios/Retichat/Bridge/LxmfFields.swift \
//     Retichat-ios/Retichat/Services/DeliveryPolicy.swift \
//     Retichat-ios/Retichat/Services/GroupStatuses.swift \
//     Retichat-ios/Retichat/Services/GroupEnvelopes.swift \
//     Retichat-ios/tests/GroupStatusFixtures.swift \
//     Retichat-ios/tests/GroupStatusVectorsTests.swift && \
//     /private/tmp/claude-501/group-status-vectors

import CryptoKit
import Foundation

let holders: [String: [String]] = ["none": [], "all": ["alice", "bob", "carol", "dave", "erin", "frank"]]

func verdictName(_ signature: Int) -> String {
    switch signature {
    case DeliveryPolicy.Signature.validated: return "verified"
    case DeliveryPolicy.Signature.invalid: return "forged"
    default: return "unverifiable"
    }
}

func outcomeName(_ signature: Int, switched: Bool) -> String {
    switch GroupStatuses.verdict(signature: signature, switched: switched) {
    case .count: return "counts"
    case .hold: return "held"
    case .ignore: return "ignored"
    }
}

/// Whether `packed`'s signature verifies under `signer`'s key (the glue's check, FakeGroupNative's).
@MainActor
func signatureVerifies(_ packed: Data, by signer: String, _ v: Vectors) -> Bool {
    FakeGroupNative().valid(packed, under: v.identities[signer]!.publicKey) == true
}

// MARK: - The file, as the phone reads it

@MainActor
func theIdentitiesAreWhatTheFileSaysPublicKeyHashAndKeyEntryDeriveFromThePrivateKey() {
    let v = Vectors.load()
    checkEqual(Set(v.identities.keys), Set(["creator", "alice", "bob", "carol", "dave", "erin", "frank", "mallory"]), "the eight identities")
    for identity in v.identities.values {
        checkEqual(TestLxmf.deliveryHash(identity.publicKey).hexString, identity.hashHex, "\(identity.name): the key's lxmf.delivery hash")
        checkEqual(GroupStatuses.keyEntry(hashHex: identity.hashHex, publicKey: identity.publicKey), identity.keyEntry,
                   "\(identity.name): the entry is hash:base64 of the key")
        let b64 = identity.keyEntry.split(separator: ":")[1]
        check(b64.count == 88 && b64.hasSuffix("==") && b64.dropLast(2).allSatisfy { $0.isLetter || $0.isNumber || $0 == "+" || $0 == "/" },
              "\(identity.name): 86 base64 characters and ==")
        checkEqual(identity.publicKey.count, 64, "\(identity.name): a 64-byte key")
        // The seed is the private key's ed25519 half: it signs for exactly this public key.
        checkEqual(Data(try! Curve25519.Signing.PrivateKey(rawRepresentation: identity.seed).publicKey.rawRepresentation),
                   Data(identity.publicKey.suffix(32)), "\(identity.name): the seed is the signing key's")
    }
    checkEqual(v.members.map { v.hashOf($0) }.joined(separator: ","),
               ((try! JSONSerialization.jsonObject(with: v.raw) as! [String: Any])["group"] as! [String: Any])["group_members"] as! String,
               "GROUP_MEMBERS is the members' hashes in the file's order")
}

/// The builder reproduces what the web signed, byte for byte: a made message is the file's kind.
@MainActor
func theTestPackingReproducesTheFilesBytesSoTheMessagesTheScenariosMakeAreTheFilesKind() {
    let v = Vectors.load()
    check(v.messages.count >= 9, "at least nine messages")
    for m in v.messages {
        let key = m.carriesKeyOf.map { holder in
            "\(v.hashOf(m.keyEntryHashOf!)):\(v.identities[holder]!.publicKey.base64EncodedString())"
        }
        let fields = TestLxmf.groupFields(retichat: m.form == "retichat", groupId: v.groupId, action: m.action,
                                          sender: v.hashOf(m.source), keyEntry: key, displayName: v.identities[m.source]!.displayName)
        checkEqual(fields, m.fieldsRaw, "\(m.name): the fields")
        let packed = TestLxmf.pack(signer: v.identities[m.signedBy]!, from: v.identities[m.source]!, to: v.identities[m.destination]!,
                                   fields: fields, at: m.timestamp)
        // CryptoKit's Ed25519 signatures are randomized, so the signature is the one thing that is not the file's bytes: it is
        // checked as a signature (below), everything else byte for byte.
        checkEqual(packed.prefix(32) + packed.suffix(from: 96), m.packed.prefix(32) + m.packed.suffix(from: 96),
                   "\(m.name): the packed message, but for the signature")
        checkEqual(signatureVerifies(packed, by: m.signedBy, v), true, "\(m.name): the signature made verifies under the signer's key")
        checkEqual(TestLxmf.sha256(m.packed.prefix(32) + Data([0x94]) + m.packed.suffix(from: 96).dropFirst()), m.messageHash,
                   "\(m.name): the message hash is the hash of destination, source and the four payload elements")
    }
    for s in v.statuses {
        let listed = s.members.map { v.message($0.message).packed }
        let fields = TestLxmf.groupFields(retichat: s.form == "retichat", groupId: v.groupId, action: "status",
                                          sender: v.hashOf(v.creator), keyEntry: nil,
                                          displayName: v.identities[v.creator]!.displayName, elements: listed)
        checkEqual(fields, s.fieldsRaw, "\(s.name): the fields")
        let packed = TestLxmf.pack(signer: v.identities[v.creator]!, from: v.identities[v.creator]!, to: v.identities[s.destination]!,
                                   fields: fields, at: s.timestamp)
        checkEqual(packed.prefix(32) + packed.suffix(from: 96), s.packed.prefix(32) + s.packed.suffix(from: 96),
                   "\(s.name): the packed message, but for the signature")
        checkEqual(signatureVerifies(packed, by: v.creator, v), true, "\(s.name): the signature made verifies under the creator's key")
    }
}

/// Every message's verdict for a receiver that holds no member's key and one that holds every member's, from the file's
/// bytes, and what it is worth: verified counts, forged is ignored, unverifiable counts until the switch and is held from it.
@MainActor
func everyMessagesVerdictForAReceiverHoldingNoMembersKeyAndOneHoldingEveryMembersIsTheFilesAndWhatItIsWorthFollows() {
    let v = Vectors.load()
    for (context, names) in holders {
        for m in v.messages {
            let native = FakeGroupNative()
            for name in names { native.know(v.identities[name]!) }
            guard let u = native.unpack(m.packed).message else { check(false, "\(m.name) does not unpack"); continue }
            checkEqual(verdictName(u.signature), m.verdict[context]!, "\(m.name): holding \(context)")
            checkEqual(outcomeName(u.signature, switched: false), m.before[context]!, "\(m.name): before the switch, holding \(context)")
            checkEqual(outcomeName(u.signature, switched: true), m.from[context]!, "\(m.name): from the switch, holding \(context)")
            // The key it carries, when it binds, is the sender's own: reported whether a key is held or not.
            let binds = m.carriesKeyOf != nil && m.keyEntryHashOf == m.source && m.carriesKeyOf == m.source
            check((u.senderKey != nil) == binds, "\(m.name): a key that binds is the sender's own")
            if binds { checkEqual(u.senderKey, v.identities[m.source]!.publicKey, "\(m.name): the key reported") }
            checkEqual(u.hash.hexString, m.messageHash.hexString, "\(m.name): the message hash")
            checkEqual(u.fieldsRaw, m.fieldsRaw, "\(m.name): the fields")
            let fields = LxmfFieldsDecoder.decode(u.fieldsRaw)
            checkEqual(fields.groupId, v.groupId, "\(m.name): the group")
            checkEqual(fields.groupAction, m.action, "\(m.name): the action")
            checkEqual(fields.groupSender, v.hashOf(m.source), "\(m.name): GROUP_SENDER is the source's")
            // Where the entries are, by form: the old top-level fields, or the Retichat field.
            let raw = [UInt8](u.fieldsRaw)
            let hasLegacyKey = raw.contains(0xA8)
            if m.form == "legacy" {
                check(raw.starts(with: [0x80 | UInt8(raw[0] & 0x0F), 0xCC, 0xA0]), "\(m.name): the entries are the old top-level fields")
                checkEqual(m.carriesKeyOf != nil, fields.groupEntries[.memberKeys] != nil, "\(m.name): the key entry is where the form puts it")
                check(hasLegacyKey == (m.carriesKeyOf != nil), "\(m.name): 0xA8 is present exactly when a key is carried")
            } else {
                check(raw.starts(with: [0x81, 0xCC, 0xD1]), "\(m.name): every entry is in the Retichat field")
            }
        }
    }
}

/// The statuses are signed by the creator, and key 10 is an array of bin holding exactly the listed messages by member hash.
@MainActor
func theStatusesAreSignedByTheCreatorAndKeyTenIsAnArrayOfBinHoldingExactlyTheListedMessagesByMemberHashAscending() {
    let v = Vectors.load()
    checkEqual(v.statuses.count, 4, "four statuses: two answers, an empty one, each in both forms")
    for s in v.statuses {
        let withCreator = FakeGroupNative()
        withCreator.know(v.identities["creator"]!)
        checkEqual(withCreator.unpack(s.packed).message?.signature, DeliveryPolicy.Signature.validated, "\(s.name): signed by the creator")
        checkEqual(FakeGroupNative().unpack(s.packed).message?.signature, DeliveryPolicy.Signature.sourceUnknown, "\(s.name): and by nobody whose key is not held")
        checkEqual(s.packed.prefix(16).hexString, v.hashOf(s.destination), "\(s.name): addressed to its recipient")
        let fields = LxmfFieldsDecoder.decode(s.fieldsRaw)
        checkEqual(fields.groupId, v.groupId, "\(s.name): the group")
        checkEqual(fields.groupAction, "status", "\(s.name): the action")
        checkEqual(fields.groupSender, v.hashOf(v.creator), "\(s.name): the creator is GROUP_SENDER")
        let elements = fields.groupStatuses ?? []
        check(elements.allSatisfy { $0 != nil }, "\(s.name): an array of bin")
        checkEqual(elements.map { $0! }, s.members.map { v.message($0.message).packed }, "\(s.name): the listed messages, byte for byte")
        let members = s.members.map(\.member)
        checkEqual(members.count, Set(members).count, "\(s.name): one element for each member")
        checkEqual(members.map { v.hashOf($0) }, members.map { v.hashOf($0) }.sorted(), "\(s.name): by member hash ascending")
        check(!members.contains("creator") && !members.contains(s.destination), "\(s.name): neither the creator's nor the recipient's own")
        for entry in s.members { checkEqual(v.message(entry.message).source, entry.member, "\(s.name): \(entry.message) is \(entry.member)'s") }
        // Key 10 is in the Retichat field whatever the form; the other entries are where the form puts them.
        checkEqual([UInt8](s.fieldsRaw).starts(with: [0x84, 0xCC, 0xA0]) || [UInt8](s.fieldsRaw).starts(with: [0x83, 0xCC, 0xA0]), s.form == "legacy",
                   "\(s.name): the entries are in the form's place")
        check(fields.groupStatuses != nil, "\(s.name): key 10 is read from the Retichat field")
    }
}

// MARK: - The receiver of a status, from the file's bytes

@MainActor
func aReceiverOfStatusToFrankDoesElementByElementWhatTheFileSaysHoldingNoMembersKeyAndEveryMembersBeforeTheSwitchAndFromItInEitherForm() {
    let v = Vectors.load()
    checkEqual(v.outcomes.count, 4, "four receiver outcomes")
    for expected in v.outcomes {
        for form in ["legacy", "retichat"] {
            let label = "holding \(expected.holds.count == 1 ? "no member's key" : "every member's key"), \(expected.switchName) the switch, \(form) form"
            let rig = GroupRig(v, me: expected.receiver, switched: expected.switchName == "from", holds: expected.holds)
            // Frank has accepted the group: the creator accepted, frank accepted, the rest are invited.
            rig.hold(accepted: true)
            rig.receive(v.status("\(expected.status)_\(form)").packed)

            checkEqual(rig.statuses(), expected.after, "\(label): every member's status afterwards")
            checkEqual(rig.store.heldRows.map { v.nameOf($0.srcHex) + "/" + $0.action }.sorted(),
                       expected.held.map { $0.member + "/" + $0.action }.sorted(), "\(label): held")
            let outcomes = expected.elements.map(\.outcome)
            let tally = rig.lastTally
            checkEqual([tally?.elements, tally?.counted, tally?.held, tally?.skipped],
                       [outcomes.count, outcomes.filter { $0 == "counted" }.count, outcomes.filter { $0 == "held" }.count,
                        outcomes.filter { $0 == "skipped" }.count].map { Optional($0) }, "\(label): the tally")
            // The notices: one for each member that counted, "left the group" for a leave, said once each.
            let said = rig.store.lines.map { ($0.joined ? "joined" : "left") + "/" + v.nameOf($0.member) }.sorted()
            let want = expected.elements.filter { $0.outcome == "counted" }
                .map { (v.message($0.message).action == "leave" ? "left" : "joined") + "/" + $0.member }.sorted()
            checkEqual(said, want, "\(label): said once each")
            // An accept element allows its member in the group the user has joined, as any accept does.
            let accepts = Set(expected.elements.filter { $0.outcome == "counted" && v.message($0.message).action == "accept" }.map(\.member))
            checkEqual(Set(rig.store.allowed.map { v.nameOf($0) }), accepts, "\(label): allowed")
            // The key an element carries is remembered as one arriving directly brings it.
            for e in expected.elements {
                let m = v.message(e.message)
                let binds = m.carriesKeyOf == m.source && m.keyEntryHashOf == m.source
                let known = rig.native.holds(v.hashOf(e.member))
                checkEqual(known, binds && e.outcome != "skipped" || expected.holds.contains(e.member),
                           "\(label): \(e.message): remembered (or held already)")
            }
        }
    }
}

@MainActor
func aStatusWithNoElementsFromTheFileIsTheCreatorsValidAnswerAndChangesNothing() {
    let v = Vectors.load()
    for form in ["legacy", "retichat"] {
        let rig = GroupRig(v, me: "alice", holds: ["creator"])
        rig.hold(accepted: true)
        let before = rig.statuses()
        rig.receive(v.status("status_empty_to_alice_\(form)").packed)
        checkEqual(rig.lastTally, StatusTally(elements: 0, counted: 0, held: 0, skipped: 0), "\(form): nothing read")
        checkEqual(rig.statuses(), before, "\(form): nothing changed")
        check(rig.store.lines.isEmpty, "\(form): nothing said")
    }
}

// MARK: - The creator, from the file's bytes

@MainActor
func aCreatorThatReceivesEachMessageAnswersItWithAStatusExactlyWhenTheFileSaysOnlyAnAcceptThatCarriesItsSendersOwnKey() {
    let v = Vectors.load()
    for (context, names) in holders {
        for m in v.messages {
            let rig = GroupRig(v, me: v.creator, holds: names)
            // The group the vectors name, created by this device: it is the creator and has accepted it.
            rig.hold(accepted: true)
            checkEqual(rig.store.chats[rig.chatId]?.creatorHex, v.hashOf(v.creator), "the creator is recorded")
            rig.receive(m.packed)
            checkEqual(rig.answeredNames(), m.creatorAnswers ? [m.source] : [], "\(m.name), the creator holding \(context)")
            // What it keeps follows what counted: a copy of exactly the bytes, or none.
            let counted = m.before[context] == "counts"
            let copies = rig.store.copyRows.values.flatMap { $0.values }.map { "\(v.nameOf($0.memberHex))/\($0.action)/\($0.packed.hexString)" }
            checkEqual(copies, counted ? ["\(m.source)/\(m.action)/\(m.packed.hexString)"] : [],
                       "\(m.name), the creator holding \(context): kept only when it counts")
        }
    }
}

/// The answer the creator builds from copies it kept is the file's status: the other members' newest counted accept or
/// leave, by member hash ascending, never its own or the recipient's.
@MainActor
func theCreatorsAnswerToFranksAcceptHoldsWhatTheFileStatusHoldsForAReceiverThatVerifiesEveryMember() {
    let v = Vectors.load()
    let rig = GroupRig(v, me: v.creator, holds: holders["all"]!)
    rig.hold(accepted: true)
    // Everything the members sent that counts reaches the creator in the file's order; frank's accept is the last.
    let frank = MessageMaker(v).msg("frank", retichat: true)
    for name in ["alice_accept_keyed_legacy", "alice_accept_keyed_retichat", "bob_leave_keyed_retichat", "bob_accept_keyless_legacy",
                 "carol_accept_forged", "dave_accept_key_not_binding", "dave_accept_forged_key_not_binding",
                 "erin_accept_keyless_legacy", "erin_leave_forged_keyless"] {
        rig.receive(v.message(name).packed)
    }
    rig.answers.removeAll()
    checkEqual(rig.receive(frank), true, "frank's accept counts")
    checkEqual(rig.answeredNames(), ["frank"], "and is answered, to frank alone")
    guard let answer = rig.answers.first else { return }
    // Alice's newest (the second), bob's leave (final: nothing replaced it), dave's keyless, erin's: what the file lists in its status
    // by member hash ascending; carol's forged one was never kept.
    let kept = answer.statuses
    let listed = v.status("status_to_frank_retichat").members.map { v.message($0.message).packed }
    check(kept.count <= listed.count + 1, "no more than the members that answered")
    check(!kept.contains(frank), "never the recipient's own")
    check(!kept.contains(v.message("carol_accept_forged").packed), "never a forged one")
    let order = kept.map { v.hashOf(v.nameOf(($0.dropFirst(16).prefix(16)).hexString)) }
    checkEqual(order, order.sorted(), "by member hash ascending")
}

// MARK: - The sender, against the file

@MainActor
func theShippedSenderWritesAlicesAcceptWithHerOwnKeyEntryInTheOldFieldBeforeTheSwitchAndInKeyNineAfter() {
    let v = Vectors.load()
    let alice = v.identities["alice"]!
    for switched in [false, true] {
        let entries = GroupEnvelopes.accept(groupId: v.groupId, selfHex: alice.hashHex, ownKey: alice.keyEntry)
        let writes = GroupEnvelopes.writes(entries, inRetichatField: switched)
        let spec = v.message(switched ? "alice_accept_keyed_retichat" : "alice_accept_keyed_legacy")
        let vector = LxmfFieldsDecoder.decode(spec.fieldsRaw)
        // The same entries as the vector, in the form it is in.
        checkEqual(vector.groupId, v.groupId, "the group")
        checkEqual(vector.groupAction, "accept", "the action")
        checkEqual(vector.groupSender, alice.hashHex, "the sender")
        checkEqual(vector.groupEntries[.memberKeys], .str(alice.keyEntry), "the entry as the file spells it")
        let expected: [GroupFieldWrite] = switched
            ? [.retichat(key: 1, value: .str(v.groupId)), .retichat(key: 4, value: .str("accept")),
               .retichat(key: 5, value: .str(alice.hashHex)), .retichat(key: 9, value: .str(alice.keyEntry))]
            : [.topLevel(field: 0xA0, value: .str(v.groupId)), .topLevel(field: 0xA3, value: .str("accept")),
               .topLevel(field: 0xA4, value: .str(alice.hashHex)), .topLevel(field: 0xA8, value: .str(alice.keyEntry))]
        checkEqual(writes, expected, "switched=\(switched): what the sender writes")
        // The vector keeps the old fields only before the switch; after it key 9 is in the Retichat field alone.
        checkEqual([UInt8](spec.fieldsRaw).contains(0xA8), !switched, "switched=\(switched): the old field 0xA8")
        checkEqual((vector.groupMemberKeys ?? [:]).count, 1, "exactly one key entry")
    }
}

@MainActor
func aCreatorsStatusIsWrittenAsTheFileHasItTheEntriesInTheFormAndKeyTenInTheRetichatFieldEitherWay() {
    let v = Vectors.load()
    let creator = v.identities["creator"]!
    for switched in [false, true] {
        let writes = GroupEnvelopes.writes(GroupEnvelopes.status(groupId: v.groupId, selfHex: creator.hashHex), inRetichatField: switched)
        let expected: [GroupFieldWrite] = switched
            ? [.retichat(key: 1, value: .str(v.groupId)), .retichat(key: 4, value: .str("status")),
               .retichat(key: 5, value: .str(creator.hashHex))]
            : [.topLevel(field: 0xA0, value: .str(v.groupId)), .topLevel(field: 0xA3, value: .str("status")),
               .topLevel(field: 0xA4, value: .str(creator.hashHex))]
        checkEqual(writes, expected, "switched=\(switched): what the status writes besides key 10")
    }
}

@MainActor
func theFilesGroupAndItsNamesAreWhatTheScenariosAssume() {
    let v = Vectors.load()
    checkEqual(v.members, ["creator", "alice", "bob", "carol", "dave", "erin", "frank"], "the members")
    checkEqual(v.creator, "creator", "the creator")
    check(v.messages.contains { $0.name == "alice_accept_keyed_legacy" }, "alice's keyed legacy accept")
    check(!v.messages.contains { $0.name == "nobody" }, "and nobody's")
}

let allTests: [(String, @MainActor () -> Void)] = [
    ("the identities are what the file says: public key, hash and key entry derive from the private key", theIdentitiesAreWhatTheFileSaysPublicKeyHashAndKeyEntryDeriveFromThePrivateKey),
    ("the test packing reproduces the file's bytes", theTestPackingReproducesTheFilesBytesSoTheMessagesTheScenariosMakeAreTheFilesKind),
    ("every message's verdict for a receiver holding no key and one holding every key is the file's", everyMessagesVerdictForAReceiverHoldingNoMembersKeyAndOneHoldingEveryMembersIsTheFilesAndWhatItIsWorthFollows),
    ("the statuses are signed by the creator and key 10 holds the listed messages by member hash", theStatusesAreSignedByTheCreatorAndKeyTenIsAnArrayOfBinHoldingExactlyTheListedMessagesByMemberHashAscending),
    ("a receiver of a status does, element by element, what the file says", aReceiverOfStatusToFrankDoesElementByElementWhatTheFileSaysHoldingNoMembersKeyAndEveryMembersBeforeTheSwitchAndFromItInEitherForm),
    ("a status with no elements is the creator's valid answer and changes nothing", aStatusWithNoElementsFromTheFileIsTheCreatorsValidAnswerAndChangesNothing),
    ("a creator answers each message exactly when the file says", aCreatorThatReceivesEachMessageAnswersItWithAStatusExactlyWhenTheFileSaysOnlyAnAcceptThatCarriesItsSendersOwnKey),
    ("the creator's answer to frank's accept holds copies by member hash, never forged, own or the recipient's", theCreatorsAnswerToFranksAcceptHoldsWhatTheFileStatusHoldsForAReceiverThatVerifiesEveryMember),
    ("the sender writes alice's accept with her own key entry in the old field before the switch and key 9 after", theShippedSenderWritesAlicesAcceptWithHerOwnKeyEntryInTheOldFieldBeforeTheSwitchAndInKeyNineAfter),
    ("a creator's status is written with the entries in the form and key 10 in the Retichat field either way", aCreatorsStatusIsWrittenAsTheFileHasItTheEntriesInTheFormAndKeyTenInTheRetichatFieldEitherWay),
    ("the file's group and its names are what the scenarios assume", theFilesGroupAndItsNamesAreWhatTheScenariosAssume),
]

@main
enum GroupStatusVectorsTests {
    @MainActor
    static func main() {
        for (name, run) in allTests {
            currentTest = name
            let before = failures.count
            run()
            print(failures.count == before ? "ok    - \(name)" : "FAIL  - \(name)")
        }
        print("\n\(allTests.count) tests, \(checks) checks, \(failures.count) failure(s)")
        exit(failures.isEmpty ? 0 : 1)
    }
}
